const LINE={length:27,tableLength:.8,tableWidth:.5,gap:.5,pxPerMeter:60};
const p=(id,name,time,mp=1,category='DÁN & ÉP',auto=false)=>({id,name,time,mp,category,auto,jig:'',setup:0,x:0,y:0});
const s948Names=[['LASER WELDING',14.94,'HÀN LASER'],['C-CLIP',12.41,'C-CLIP'],['ATTACH SHEET GASKET (21, 22, 23 P)',15.96,'METAL SHEET'],['ATTACH SHEET GASKET (19, 20, 24, 25 P)',14.96,'METAL SHEET'],['TAPE SPONGE SENSOR FA, TAPE C-CLIP FIX',15.13],['ATTACH METAL SHEET (7, 8, 11 P)',13.92,'METAL SHEET'],['ATTACH METAL SHEET (3, 4, 5, 12, 14 P)',15.38,'METAL SHEET'],['ATTACH METAL SHEET (1, 2, 9, 10, 13 P)',14.83,'METAL SHEET'],['ATTACH METAL SHEET (16, 18 P)',12.93,'METAL SHEET'],['ATTACH METAL SHEET (15, 17 P)',13.04,'METAL SHEET'],['TAPE VC TOP, SPONGE BIT, SPONGE FOD / PRESS',16.16],['MIC HOLD DINO CHECK',12.92,'TEST/KIỂM TRA'],['PROTECT VINYL REAR TOP/BTM',15.42,'DÁN VINYL BẢO VỆ'],['CLEANING',15.88,'LÀM SẠCH'],['IQC',13.70,'KIỂM TRA ĐẦU VÀO'],['VISION LASER CHECK',15.29,'TEST/KIỂM TRA'],['TAPE VC BTM, SPONGE DDI',14.58],['VAPOR CHAMBER ATTACH',14.72,'GẮN TAY'],['TAPE ABSORBER FOD MMP / PRESS',15.73],['TAPE FRONT MID ATTACH / PRESS',12.90],['SPONGE BIT UPPER + TAPE FRONT GR',14.95],['SPONGE TELE CAM CONN ATTACH / PRESS',15.15],['RUBBER UW CAM + WIDE CAM / PRESS',14.73],['SIDE KEY FPCB_BRK ASSY',11.09,'GẮN MẠCH'],['SIDE KEY ATTACH',14.65,'GẮN TAY'],['LOCKER S PEN, WATER SOAK / PRESS',14.48],['GẮN PHÍM + ROLLING',13.78,'ROLLING'],['EJECTOR PIN + RUBBER HOLDER',12.28,'GẮN TAY'],['S PEN COVER + MIC 2 / PRESS',15.50],['SPONGE VT CAM + MIC 1',14.32],['AIR VENT ASSY / PRESS',14.72,'AIRVENT'],['SPONGE UW CAM CONN + WIDE CAM',15.15],['AGING',10.25,'AGING'],['WPT TEST',15.55,'TEST TÍNH NĂNG'],['S-PEN COVER CHECK',10.50,'TEST/KIỂM TRA'],['WLT TEST',15.59,'TEST TÍNH NĂNG'],['VSWR TEST + CHECK VISION',16.06,'TEST TÍNH NĂNG'],['OQC',15.85,'KIỂM TRA ĐẦU RA']];
const b3Names=[['IQC',14.01,'KIỂM TRA ĐẦU VÀO'],['CLEANING + LOCKER SPEN',11.25,'LÀM SẠCH'],['SIDE KEY FPCB_BRK ASSY',12.28,'GẮN MẠCH'],['SIDE KEY ATTACH',10.69,'GẮN TAY'],['GẮN/ÉP + WATER LABEL + MARKING',10.11],['GẮN PHÍM + ROLLING',13.87,'ROLLING'],['RUBBER S PEN HOLDER + CHỐT SIM',11.65],['S PEN COVER + DINO SIM PIN',15.58],['SPONGE MESH MIC TOP + VT CAM',13],['AIR VENT ASSY / PRESS',12.3,'AIRVENT'],['UW CAM CONN + WIDE CAM BTM',13.53],['REMOVE LINER + LẮP TRAY SIM',11.03,'GẮN TAY'],['WPT TEST',16.22,'TEST TÍNH NĂNG'],['TEST SPEN + THÁO TRAY SIM',8.43,'TEST TÍNH NĂNG'],['WLT TEST',15.98,'TEST TÍNH NĂNG'],['VSWR TEST + CHECK VISION',15.26,'TEST TÍNH NĂNG'],['OQC',15.22,'KIỂM TRA ĐẦU RA']];
function buildModel(name,version,rows,prefix){const processes=rows.map((r,i)=>p(prefix+(i+1),r[0],r[1],/WLT|VSWR|C-CLIP/.test(r[0])?0:1,r[2]||'DÁN & ÉP',/WLT|VSWR|C-CLIP/.test(r[0])));const model={name,version,processes,note:'Dữ liệu khởi tạo từ file IST layout Product.xlsm'};arrange(model);return model}
const seed={models:{s948:buildModel('S948','Ver 0.3',s948Names,'s'),s948b3:buildModel('S948 Block 3','Ver 0.3',b3Names,'b')},versions:[]};
for(const [catalogName,rows] of Object.entries(window.LOB_CATALOG||{})){
  const normalized=catalogName.replaceAll('*','').trim().toLowerCase();
  const exists=Object.values(seed.models).some(m=>m.name.toLowerCase()===normalized||m.name.toLowerCase()===catalogName.toLowerCase());
  if(exists)continue;
  const key='catalog-'+catalogName.toLowerCase().replace(/[^a-z0-9]+/g,'-');
  seed.models[key]=buildModel(catalogName,'Imported',rows.map(r=>[r.name,0,r.category]),key+'-');
  seed.models[key].note='Tên công đoạn lấy từ sheet Thông tin công đoạn từng model; cần nhập T/T.';
}
function arrange(model){model.processes.forEach((s,i)=>{const physical=i*(LINE.tableLength+LINE.gap),lane=Math.floor(physical/LINE.length),meter=physical%LINE.length;s.x=Math.round(meter*LINE.pxPerMeter);s.y=60+lane*94;});}
let state=structuredClone(seed),currentKey='s948',selectedId=null,history=[],session={role:'viewer',email:''},saveTimer=null;
const $=id=>document.getElementById(id),canEdit=()=>['owner','editor'].includes(session.role),model=()=>state.models[currentKey];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function metrics(){const a=model().processes,neck=Math.max(0,...a.map(x=>+x.time||0)),sum=a.reduce((n,x)=>n+(+x.time||0),0),mp=a.reduce((n,x)=>n+(+x.mp||0),0);return{neck,sum,mp,uph:neck?3600/neck:0,lob:neck&&a.length?sum/(a.length*neck):0}}
function snapshot(){if(!canEdit())return;history.push(structuredClone(state));if(history.length>30)history.shift()}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function request(url,options={}){const response=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Không thể kết nối máy chủ.');return body}
async function boot(){renderRuler();try{const result=await request('/api/layouts');session=result.user||session;for(const row of result.layouts||[])state.models[row.id]=row.data;const latest=result.layouts?.find(r=>r.is_latest&&r.model==='S948');if(latest)currentKey=latest.id}catch(error){toast('Đang dùng dữ liệu mẫu: '+error.message)}applyRole();renderAll()}
function applyRole(){document.body.classList.toggle('readonly',!canEdit());$('roleBadge').textContent=session.role==='owner'?'Chủ sở hữu · chỉnh sửa':session.role==='editor'?'Được phép chỉnh sửa':'Chế độ chỉ xem';$('roleBadge').className='role-badge '+(canEdit()?'edit':'view');$('editorsBtn').hidden=session.role!=='owner';$('saveState').innerHTML=canEdit()?'<i></i>Đã đồng bộ':'Chỉ xem công khai';if(!canEdit()&&!session.email&&!document.getElementById('signinBtn'))$('saveState').insertAdjacentHTML('afterend','<a id="signinBtn" class="btn ghost" href="/signin-with-chatgpt?return_to=/" target="_top">Đăng nhập để sửa</a>')}
function renderAll(){renderModels();renderList();renderCanvas();renderMetrics();renderInspector();renderVersions()}
function renderModels(){const entries=Object.entries(state.models).sort((a,b)=>a[1].name.localeCompare(b[1].name)||b[1].version.localeCompare(a[1].version));$('modelSelect').innerHTML=entries.map(([k,m])=>`<option value="${esc(k)}" ${k===currentKey?'selected':''}>${esc(m.name)} · ${esc(m.version)}</option>`).join('');$('layoutTitle').textContent=`Layout ${model().name} · ${model().version}`}
function renderMetrics(){const m=metrics();$('metricLob').textContent=(m.lob*100).toFixed(1)+'%';$('metricNeck').textContent=m.neck.toFixed(2);$('metricUph').textContent=m.uph.toFixed(0);$('metricCount').textContent=model().processes.length;$('metricMp').textContent=m.mp+' nhân lực';$('capacityText').textContent=Math.floor((LINE.length+LINE.gap)/(LINE.tableLength+LINE.gap))+' bàn / cạnh'}
function renderRuler(){$('meterRuler').innerHTML=Array.from({length:28},(_,i)=>`<span style="left:${i*LINE.pxPerMeter}px">${i}m</span>`).join('')}
function renderList(){const q=$('searchInput').value.toLowerCase();$('processList').innerHTML=model().processes.filter(x=>x.name.toLowerCase().includes(q)).map((x,i)=>`<div class="process-item ${x.id===selectedId?'active':''}" data-id="${esc(x.id)}"><span class="num">${i+1}</span><span class="pname">${esc(x.name)}</span><span class="ptime">${(+x.time).toFixed(2)}s</span></div>`).join('');document.querySelectorAll('.process-item').forEach(el=>el.onclick=()=>select(el.dataset.id))}
function renderCanvas(){const box=$('layoutCanvas'),neck=metrics().neck;box.querySelectorAll('.station').forEach(x=>x.remove());model().processes.forEach((s,i)=>{const el=document.createElement('div');el.className=`station ${s.id===selectedId?'active':''} ${+s.time===neck?'neck':''} ${s.auto?'auto':''}`;el.dataset.id=s.id;el.style.left=s.x+'px';el.style.top=s.y+'px';el.title=`${i+1}. ${s.name}\nT/T: ${s.time}s · ${s.auto?'AUTO':s.mp+' MP'}\nVị trí: ${(s.x/LINE.pxPerMeter).toFixed(1)}m`;el.innerHTML=`<div class="station-no">${i+1}</div><div class="station-name">${esc(s.name)}</div><div class="station-meta"><span>${(+s.time).toFixed(2)}s</span><span>${s.auto?'AUTO':s.mp+'MP'}</span></div>`;if(canEdit())el.onpointerdown=startDrag;el.onclick=()=>select(s.id);box.appendChild(el)})}
function select(id){selectedId=id;renderList();renderCanvas();renderInspector();if(innerWidth<=1050)$('inspector').classList.add('open')}
function renderInspector(){const s=model().processes.find(x=>x.id===selectedId),form=$('editForm'),empty=$('emptyInspector');if(!s){form.classList.remove('visible');empty.style.display='block';$('stationBadge').textContent='TRẠM —';$('stationTitle').textContent='Chọn một trạm';return}empty.style.display='none';form.classList.add('visible');const i=model().processes.indexOf(s);$('stationBadge').textContent=`TRẠM ${String(i+1).padStart(2,'0')} · ${(s.x/LINE.pxPerMeter).toFixed(1)}m`;$('stationTitle').textContent=s.name;$('nameInput').value=s.name;$('timeInput').value=s.time;$('mpInput').value=s.mp;$('categoryInput').value=s.category;$('autoInput').checked=s.auto;$('jigInput').value=s.jig||'';$('setupInput').value=s.setup||0;form.querySelectorAll('input,textarea,select').forEach(x=>x.disabled=!canEdit())}
function renderVersions(){const list=Object.entries(state.models).filter(([,m])=>m.name===model().name).sort((a,b)=>b[1].version.localeCompare(a[1].version));$('versionList').innerHTML=list.map(([,m],i)=>`<div class="version-entry"><b>${esc(m.version)} ${i===0?'<span class="latest">Mới nhất</span>':''}</b><small>${esc(m.note||'Không có ghi chú')}</small></div>`).join('')}
function startDrag(e){if(!canEdit())return;const el=e.currentTarget,s=model().processes.find(x=>x.id===el.dataset.id),canvas=$('layoutCanvas'),r=canvas.getBoundingClientRect(),ox=e.clientX-r.left-s.x,oy=e.clientY-r.top-s.y;snapshot();select(s.id);el.setPointerCapture(e.pointerId);let moved=false;el.onpointermove=ev=>{moved=true;const rawX=Math.max(0,Math.min(LINE.length*LINE.pxPerMeter-72,ev.clientX-r.left-ox));s.x=Math.round(rawX/(LINE.gap*LINE.pxPerMeter))*(LINE.gap*LINE.pxPerMeter);s.y=Math.max(40,Math.min(canvas.clientHeight-55,Math.round((ev.clientY-r.top-oy)/47)*47));el.style.left=s.x+'px';el.style.top=s.y+'px'};el.onpointerup=()=>{el.onpointermove=null;if(moved){scheduleSave();renderInspector();toast('Đã cập nhật vị trí trạm')}}}
async function saveCurrent(isLatest=true){if(!canEdit())return;clearTimeout(saveTimer);$('saveState').innerHTML='<i></i>Đang đồng bộ…';try{const id=currentKey.includes('::')?currentKey:`${model().name}::${model().version}`;await request('/api/layouts',{method:'POST',body:JSON.stringify({id,data:model(),isLatest})});if(id!==currentKey){state.models[id]=model();delete state.models[currentKey];currentKey=id}$('saveState').innerHTML='<i></i>Đã đồng bộ'}catch(error){$('saveState').textContent='Chưa đồng bộ';toast(error.message);throw error}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCurrent().catch(()=>{}),700)}
function downloadTemplate(){const rows=[['model','version','process_no','process_name','category','tt_seconds','mp','auto','position_meter','lane','jig_name','setup_minutes'],...model().processes.map((s,i)=>[model().name,model().version,i+1,s.name,s.category,s.time,s.mp,s.auto?'YES':'NO',(s.x/LINE.pxPerMeter).toFixed(1),Math.max(1,Math.round((s.y-60)/94)+1),s.jig||'',s.setup||0])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`LOB_${model().name}_${model().version}.csv`;a.click();URL.revokeObjectURL(a.href)}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
async function importCSV(file){if(!canEdit())return toast('Bạn không có quyền nhập dữ liệu.');const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('File không có dữ liệu.');const headers=rows[0].map(x=>x.trim().replace(/^\ufeff/,'')),idx=n=>headers.indexOf(n);for(const required of ['process_name','tt_seconds'])if(idx(required)<0)throw new Error(`Thiếu cột ${required}.`);snapshot();const imported=rows.slice(1).filter(r=>r[idx('process_name')]?.trim()).map((r,i)=>{const s=p('imp'+Date.now()+i,r[idx('process_name')].trim(),Math.max(0,+r[idx('tt_seconds')]||0),Math.max(0,+r[idx('mp')]||0),r[idx('category')]||'DÁN & ÉP',(r[idx('auto')]||'').toUpperCase()==='YES');s.x=Math.max(0,(+r[idx('position_meter')]||i*1.3)*LINE.pxPerMeter);s.y=60+Math.max(0,(+r[idx('lane')]||1)-1)*94;s.jig=r[idx('jig_name')]||'';s.setup=Math.max(0,+r[idx('setup_minutes')]||0);return s});model().processes=imported;if(idx('model')>=0&&rows[1][idx('model')])model().name=rows[1][idx('model')];if(idx('version')>=0&&rows[1][idx('version')])model().version=rows[1][idx('version')];await saveCurrent();renderAll();toast(`Đã nhập ${imported.length} công đoạn`)}
async function loadEditors(){const result=await request('/api/editors');$('editorsList').innerHTML=result.editors.length?result.editors.map(e=>`<div class="editor-row"><span>${esc(e.email)}</span><button type="button" data-email="${esc(e.email)}">Xóa</button></div>`).join(''):'<small>Chưa cấp quyền cho email nào.</small>';document.querySelectorAll('.editor-row button').forEach(b=>b.onclick=async()=>{await request('/api/editors?email='+encodeURIComponent(b.dataset.email),{method:'DELETE'});loadEditors()})}
$('modelSelect').onchange=e=>{currentKey=e.target.value;selectedId=null;renderAll()};$('searchInput').oninput=renderList;
$('editForm').onsubmit=e=>{e.preventDefault();if(!canEdit())return;const s=model().processes.find(x=>x.id===selectedId);if(!s)return;snapshot();s.name=$('nameInput').value.trim()||s.name;s.time=Math.max(0,+$('timeInput').value||0);s.auto=$('autoInput').checked;s.mp=s.auto?0:Math.max(0,+$('mpInput').value||0);s.category=$('categoryInput').value;s.jig=$('jigInput').value.trim();s.setup=Math.max(0,+$('setupInput').value||0);renderAll();scheduleSave();toast('Đã áp dụng thay đổi')};
$('addBtn').onclick=()=>{if(!canEdit())return;snapshot();const s=p('p'+Date.now(),'Công đoạn mới',10,1);s.x=0;s.y=60;model().processes.push(s);selectedId=s.id;renderAll();select(s.id);scheduleSave()};
$('deleteBtn').onclick=()=>{if(!canEdit()||!selectedId)return;snapshot();model().processes=model().processes.filter(x=>x.id!==selectedId);selectedId=null;renderAll();scheduleSave();toast('Đã xóa công đoạn')};
$('undoBtn').onclick=()=>{if(!canEdit()||!history.length)return toast('Không còn thao tác để hoàn tác');state=history.pop();selectedId=null;renderAll();scheduleSave();toast('Đã hoàn tác')};
$('duplicateBtn').onclick=()=>{if(!canEdit())return;snapshot();const base=model(),key='draft'+Date.now(),copy=structuredClone(base);copy.name=base.name+' Copy';copy.version='Ver 0.1';copy.note='Nhân bản từ '+base.name+' '+base.version;copy.processes.forEach((x,i)=>x.id=key+'-'+i);state.models[key]=copy;currentKey=key;selectedId=null;renderAll();toast('Đã tạo bản sao; hãy lưu version khi hoàn tất')};
$('resetBtn').onclick=()=>{if(!canEdit())return;state=structuredClone(seed);currentKey='s948';selectedId=null;renderAll();toast('Đã khôi phục dữ liệu mẫu cục bộ')};$('printBtn').onclick=()=>window.print();$('closeInspector').onclick=()=>{$('inspector').classList.remove('open');selectedId=null;renderInspector();renderCanvas();renderList()};
$('templateBtn').onclick=downloadTemplate;$('importBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{const file=e.target.files[0];if(file)importCSV(file).catch(err=>toast(err.message));e.target.value=''};
$('saveVersionBtn').onclick=()=>{if(!canEdit())return;$('versionName').value=model().version;$('versionNote').value='';$('versionDialog').showModal()};
$('versionForm').addEventListener('submit',async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();snapshot();const copy=structuredClone(model());copy.version=$('versionName').value.trim()||copy.version;copy.note=$('versionNote').value.trim();const id=`${copy.name}::${copy.version}`;state.models[id]=copy;currentKey=id;$('versionDialog').close();await saveCurrent(true);renderAll();toast('Đã lưu phiên bản mới nhất')});
$('editorsBtn').onclick=async()=>{$('editorsDialog').showModal();await loadEditors()};$('editorsForm').onsubmit=async e=>{e.preventDefault();await request('/api/editors',{method:'POST',body:JSON.stringify({email:$('editorEmail').value})});$('editorEmail').value='';await loadEditors();toast('Đã cấp quyền chỉnh sửa')};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){$('undoBtn').click();e.preventDefault()}});
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;try{c.registerTool({name:'read_lob_summary',title:'Đọc chỉ số LOB',description:'Đọc chỉ số cân bằng của model và version đang mở.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{model:model().name,version:model().version,...metrics(),lineMeters:LINE.length}}})}catch{}}
boot();registerTools();
